def get_max_triples(n):
    # Generate the sequence A
    A = [i * i - i + 1 for i in range(1, n + 1)]

    # Initialize the count of valid triples
    count = 0

    # Iterate through all possible combinations of three distinct elements in A
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                # Check if the sum of the current triple is divisible by 3
                if (A[i] + A[j] + A[k]) % 3 == 0:
                    count += 1

    return count

def right_angle_triangle(a, b, c):
    # Check if any combination of sides forms a right angle
    return (a**2 + b**2 == c**2) or (a**2 + c**2 == b**2) or (b**2 + c**2 == a**2)

def do_algebra(operator_list, operand_list):
    # Construct the algebraic expression from the operator and operand lists
    expression = ""
    for i in range(len(operator_list)):
        expression += str(operand_list[i])
        if i < len(operator_list) - 1:
            expression += operator_list[i]

    # Evaluate the constructed expression using the eval function
    result = eval(expression)

    return result

def solve(s):
    # Check if there are any alphabetic characters in the string
    has_alpha = any(char.isalpha() for char in s)

    if has_alpha:
        # Swap the case of each alphabetic character
        return ''.join(char.swapcase() if char.isalpha() else char for char in s)
    else:
        # Reverse the string if no alphabetic characters are found
        return s[::-1]

def Strongest_Extension(class_name, extensions):
    def calculate_strength(extension):
        upper_count = sum(1 for char in extension if char.isupper())
        lower_count = sum(1 for char in extension if char.islower())
        return upper_count - lower_count

    strongest_extension = ""
    max_strength = float('-inf')

    for extension in extensions:
        strength = calculate_strength(extension)
        if strength > max_strength:
            max_strength = strength
            strongest_extension = extension

    return f"{class_name}.{strongest_extension}"
